examples.query:
mutation CreateWebhook($endpoint: String!, $name: String!) {
  createWebhook(endpoint: $endpoint, name: $name)
}

mutation CreateWebhook($endpoint: String!, $name: String!) {
  createWebhook(endpoint: $endpoint, name: $name)
}

query Webhooks($endpoint: String) {
  webhooks(endpoint: $endpoint) {
    endpoint
    name
    is_active
  }
}

query Webhooks {
  webhooks {
    endpoint
    name
    is_active
  }
}

mutation UpdateWebhook($endpoint: String!, $is_active: Boolean) {
  updateWebhook(endpoint: $endpoint, is_active: $is_active)
}

mutation UpdateWebhook($endpoint: String!, $name: String) {
  updateWebhook(endpoint: $endpoint, name: $name)
}

query WebhookEvents($endpoint: String, $limit: Int) {
  webhookEvents(endpoint: $endpoint, limit: $limit) {
    events {
      id
      event_id
      event
      result
      status_code
      error
      retry_count
      started_at
    }
    last_evaluated_key
  }
}

query WebhookEvents($event_id: ID) {
  webhookEvents(event_id: $event_id) {
    events {
      id
      event_id
      event
      result
      status_code
      retry_count
      started_at
    }
  }
}

query WebhookVerificationKeys {
  jwks {
    keys {
      kid
      kty
      crv
      alg
      use
      x
    }
  }
}
